    void drainCompat(MediaCodec.BufferInfo info)throws Exception{for(int i=0;i<12;i++){int index=compat.dequeueOutputBuffer(info,0);if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){compatFormat=compat.getOutputFormat();compatHeaders=csd(compatFormat);System.out.println("BROWSER_COMPAT_FORMAT "+compatFormat);prepareBrowser();continue;}if(index<0)return;try{if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0&&baseUs>=0){ByteBuffer b=compat.getOutputBuffer(index).duplicate();b.position(info.offset);b.limit(info.offset+info.size);byte[] bytes=new byte[info.size];b.get(bytes);compatFrames++;if(browserMux!=null)browserMux.emit(true,bytes,Math.max(0,info.presentationTimeUs-baseUs),info.flags);}}finally{compat.releaseOutputBuffer(index,false);}}}
    void drainCompatAudio(MediaCodec.BufferInfo info)throws Exception{for(int i=0;i<12;i++){int index=compatAudio.dequeueOutputBuffer(info,0);if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){compatAudioFormat=compatAudio.getOutputFormat();prepareBrowser();continue;}if(index<0)return;try{if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0&&baseUs>=0&&info.presentationTimeUs>=baseUs&&browserMux!=null){ByteBuffer b=compatAudio.getOutputBuffer(index).duplicate();b.position(info.offset);b.limit(info.offset+info.size);browserMux.emit(false,buffer(b),info.presentationTimeUs-baseUs,info.flags);}}finally{compatAudio.releaseOutputBuffer(index,false);}}}
    void serveBrowser(Socket socket,OutputStream out,LiveChannel channel,MediaCodec encoder)throws Exception{if(channel==null){reply(out,"503 Service Unavailable","text/plain","Waiting for encoder output format.");return;}channel.serve(this,socket,out,encoder);}
    String prop(String key)throws Exception{Class<?> sp=Class.forName("android.os.SystemProperties");return (String)sp.getMethod("get",String.class).invoke(null,key);}
    void rootCommand(String command)throws Exception{java.lang.Process p=new ProcessBuilder("/system/bin/sh","-c",command).redirectErrorStream(true).start();ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=p.getInputStream()){byte[] buffer=new byte[2048];int n;while((n=in.read(buffer))>0)b.write(buffer,0,n);}int result=p.waitFor();if(result!=0)throw new IOException(command+": "+b.toString());}
    boolean restore(String key,String value){try{if(value.isEmpty()){if(!prop(key).isEmpty())rootCommand("resetprop -n --delete "+key);}else {if(!value.matches("[A-Za-z0-9_.+-]+"))throw new IOException("Unexpected original value");rootCommand("resetprop -n "+key+" "+value);}return prop(key).equals(value);}catch(Exception e){System.out.println("RESTORE_FAILED "+key+" "+e);return false;}}
    synchronized void close(){if(closed)return;closed=true;running=false;state="Stopped";try{if(display!=null)display.release();}catch(Exception ignored){}if(desktop!=null)desktop.close();if(cadence!=null)cadence.close();if(gpu!=null)gpu.close();try{if(sound!=null)sound.stop();if(audioThread!=null)audioThread.join(1500);}catch(Exception ignored){}try{if(sound!=null)sound.release();}catch(Exception ignored){}for(MediaCodec c:new MediaCodec[]{video,audio,compat,compatAudio})if(c!=null){try{c.stop();}catch(Exception ignored){}try{c.release();}catch(Exception ignored){}}try{if(muxer!=null){if(muxStarted)muxer.stop();muxer.release();}}catch(Exception e){System.out.println("MUX_FINALIZE_FAILED "+e);}try{if(surface!=null)surface.release();if(compatSurface!=null)compatSurface.release();if(server!=null)server.close();}catch(Exception ignored){}for(Client c:clients)c.close();if(browserMux!=null)browserMux.close();if(nativeMux!=null)nativeMux.close();if(mkvMux!=null)mkvMux.close();if(changed){boolean a=restore("persist.pvr.screen.record.fps",oldFps);boolean b=restore("debug.pxr.presentation.throttle",oldThrottle);if(a&&b&&rollback!=null)rollback.delete();}try{if(sessionLock!=null)sessionLock.release();if(lockFile!=null)lockFile.close();}catch(Exception ignored){}System.out.println("STOPPED frames="+frames+" file="+file+" error="+error);}
    static class Sample{boolean video;byte[] bytes;long us;int flags;Sample(boolean v,byte[] b,long u,int f){video=v;bytes=b;us=u;flags=f;}}
    static class Client{
        Socket socket;boolean ready=false,discontinuity=false;ArrayBlockingQueue<byte[]> queue=new ArrayBlockingQueue<>(32);
        Client(Socket s){socket=s;}
        synchronized boolean enqueue(byte[] packet,boolean key,byte[] tables){
            if(!ready&&!key)return true;
            boolean overflow=queue.remainingCapacity()==0;
            if(overflow){queue.clear();ready=false;discontinuity=true;}
            if(key){byte[] marker=discontinuity?TransportStream.discontinuity():new byte[0];ByteArrayOutputStream b=new ByteArrayOutputStream();b.write(marker,0,marker.length);b.write(tables,0,tables.length);b.write(packet,0,packet.length);packet=b.toByteArray();ready=true;discontinuity=false;}
            if(ready)queue.offer(packet);
            return !overflow;
        }
        void close(){try{socket.close();}catch(Exception ignored){}}
    }
